import sys
import re


def main():
    text = sys.stdin.read()

    # Values start at 0 until something assigns them.
    env = {}

    # Accept either "<-" or ":=" as the assignment arrow.
    # Group 1 is the variable name, group 2 is the expression up to the semicolon.
    stmt_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*(?:<-|:=)\s*(.+?)\s*;?\s*$')

    for raw in text.splitlines():
        # Strip "//" comments.
        line = raw.split('//', 1)[0].strip()
        if not line:
            continue

        # A line may hold several statements separated by ';'.
        for part in line.split(';'):
            part = part.strip()
            if not part:
                continue

            m = stmt_re.match(part)
            if not m:
                continue
            var, expr = m.group(1), m.group(2)

            # Turn the expression into Python: "mod" becomes "%".
            pyexpr = re.sub(r'\bmod\b', '%', expr)

            # Allow only identifiers, digits, whitespace, operators and parentheses.
            if not re.fullmatch(r'[\w\s+\-*/%()]*', pyexpr):
                continue

            # Fill in each identifier with its current value (0 if never set).
            def repl(mm):
                name = mm.group(0)
                if name.isdigit():
                    return name
                return str(env.get(name, 0))

            pyexpr2 = re.sub(r'\b[A-Za-z_]\w*\b|\b\d+\b', repl, pyexpr)

            try:
                val = eval(pyexpr2, {"__builtins__": {}}, {})
            except Exception:
                continue
            env[var] = int(val)

    a = env.get('a', 0)
    b = env.get('b', 0)
    t = env.get('TMP', 0)
    print(f"a ?= {a}; b ?= {b}; TMP ?= {t};")


if __name__ == "__main__":
    main()
